            match roles.compare_exchange_weak(r, r | CONSUMER, Ordering::AcqRel, Ordering::Acquire)
            {
                Ok(_) => break,
                Err(actual) => r = actual,
            }
        }
        match self.segs.load_consumer() {
            Ok(cp) => Ok(MpscConsumer::resume(self.segs, cp)),
            Err(e) => {
                roles.fetch_and(!CONSUMER, Ordering::Release);
                Err(e)
            }
        }
    }

